class ResultModel { final String id,studentId,examId,courseId; final double score; final bool passed; final DateTime submittedAt; const ResultModel({required this.id,required this.studentId,required this.examId,required this.courseId,required this.score,required this.passed,required this.submittedAt}); Map<String,dynamic> toMap()=>{'studentId':studentId,'examId':examId,'courseId':courseId,'score':score,'passed':passed,'submittedAt':submittedAt.toIso8601String()}; factory ResultModel.fromMap(String id,Map<String,dynamic> m)=>ResultModel(id:id,studentId:m['studentId']??'',examId:m['examId']??'',courseId:m['courseId']??'',score:(m['score']??0).toDouble(),passed:m['passed']??false,submittedAt:DateTime.tryParse(m['submittedAt']??'')??DateTime.now()); }